85: static const char g_statusCodeError[] = "http status code is not OK";
86: 
87: Qiniu_Error Qiniu_callex(CURL *curl, Qiniu_Buffer *resp, Qiniu_Json **ret, Qiniu_Bool simpleError,
88:                          Qiniu_Buffer *resph)
89: {
90:     Qiniu_Error err;
91:     CURLcode curlCode;
92:     long httpCode;
93:     Qiniu_Json *root;
94: 
95:     curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, Qiniu_Buffer_Fwrite);
96:     curl_easy_setopt(curl, CURLOPT_WRITEDATA, resp);
97:     if (resph != NULL)
98:     {
99:         curl_easy_setopt(curl, CURLOPT_HEADERFUNCTION, Qiniu_Buffer_Fwrite);
100:         curl_easy_setopt(curl, CURLOPT_WRITEHEADER, resph);
101:     }
102: 
103:     curlCode = curl_easy_perform(curl);
104: 
105:     if (curlCode == 0)
106:     {
107:         curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &httpCode);
108:         if (Qiniu_Buffer_Len(resp) != 0)
109:         {
110:             root = cJSON_Parse(Qiniu_Buffer_CStr(resp));
111:         }
112:         else
113:         {
114:             root = NULL;
115:         }
116:         *ret = root;
117:         err.code = (int)httpCode;
118:         if (httpCode / 100 != 2)
119:         {
120:             if (simpleError)
121:             {
122:                 err.message = g_statusCodeError;
123:             }
124:             else
125:             {
126:                 err.message = Qiniu_Json_GetString(root, "error", g_statusCodeError);
127:             }
128:         }
129:         else
130:         {
131:             err.message = "OK";
132:         }
133:     }
134:     else
135:     {
136:         *ret = NULL;
137:         err.code = curlCode;
138:         err.message = "curl_easy_perform error";
139:     }
140: 
141:     return err;
142: }
