437: CURL *Qiniu_Client_reset(Qiniu_Client *self)
438: {
439:     CURL *curl = (CURL *)self->curl;
440: 
441:     curl_easy_reset(curl);
442:     Qiniu_Buffer_Reset(&self->b);
443:     Qiniu_Buffer_Reset(&self->respHeader);
444:     if (self->root != NULL)
445:     {
446:         cJSON_Delete(self->root);
447:         self->root = NULL;
448:     }
449: 
450:     // Set this option to allow multi-threaded application to get signals, etc
451:     // Setting CURLOPT_NOSIGNAL to 1 makes libcurl NOT ask the system to ignore SIGPIPE signals
452:     // See also https://curl.haxx.se/libcurl/c/CURLOPT_NOSIGNAL.html
453:     // FIXED by fengyh 2017-03-22 10:30
454:     curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1);
455: 
456:     return curl;
457: }
