487: static Qiniu_Error Qiniu_Client_callWithBody(
488:     Qiniu_Client *self, Qiniu_Json **ret, const char *url,
489:     const char *body, Qiniu_Int64 bodyLen, const char *mimeType, const char *md5)
490: {
491:     int retCode = 0;
492:     Qiniu_Error err;
493:     const char *ctxType;
494:     char ctxLength[64], userAgent[64];
495:     Qiniu_Header *headers;
496:     CURL *curl = (CURL *)self->curl;
497:     err = Qiniu_Client_config(self);
498:     if (err.code != 200)
499:     {
500:         return err;
501:     }
502: 
503:     curl_easy_setopt(curl, CURLOPT_POST, 1);
504: 
505:     if (mimeType == NULL)
506:     {
507:         ctxType = "Content-Type: application/octet-stream";
508:     }
509:     else
510:     {
511:         ctxType = Qiniu_String_Concat2("Content-Type: ", mimeType);
512:     }
513: 
514:     Qiniu_snprintf(ctxLength, 64, "Content-Length: %lld", bodyLen);
515:     Qiniu_snprintf(userAgent, 64, "UserAgent: QiniuC/%s", version);
516:     headers = curl_slist_append(NULL, ctxLength);
517:     headers = curl_slist_append(headers, ctxType);
518:     headers = curl_slist_append(headers, userAgent);
519:     headers = curl_slist_append(headers, "Expect:");
520:     if (md5 != NULL)
521:     {
522:         char *contentMd5 = Qiniu_String_Concat2("Content-MD5: ", md5);
523:         headers = curl_slist_append(headers, contentMd5);
524:     }
525: 
526:     if (self->auth.itbl != NULL)
527:     {
528:         if (body == NULL)
529:         {
530:             bodyLen = 0;
531:         }
532:         err = Qiniu_Do_Auth(self, "POST", &headers, url, body, (size_t)bodyLen);
533:         if (err.code != 200)
534:         {
535:             return err;
536:         }
537:     }
538: 
539:     curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
540: 
541:     err = Qiniu_callex(curl, &self->b, &self->root, Qiniu_False, &self->respHeader);
542: 
543:     curl_slist_free_all(headers);
544:     if (mimeType != NULL)
545:     {
546:         free((void *)ctxType);
547:     }
548: 
549:     *ret = self->root;
550:     return err;
551: }
