179: static Qiniu_Error Qiniu_Mac_Auth(
180: 	void *self, Qiniu_Header **header, const char *url, const char *addition, size_t addlen)
181: {
182: 	Qiniu_Error err;
183: 	char *auth;
184: 	char *enc_digest;
185: 	char digest[EVP_MAX_MD_SIZE + 1];
186: 	unsigned int digest_len = sizeof(digest);
187: 	Qiniu_Mac mac;
188: 
189: 	char const *path;
190: 	err = Qiniu_Mac_Parse_Url(url, NULL, NULL, &path, NULL);
191: 	if (err.code != 200)
192: 	{
193: 		return err;
194: 	}
195: 
196: 	if (self)
197: 	{
198: 		mac = *(Qiniu_Mac *)self;
199: 	}
200: 	else
201: 	{
202: 		mac.accessKey = QINIU_ACCESS_KEY;
203: 		mac.secretKey = QINIU_SECRET_KEY;
204: 	}
205: 	Qiniu_Mac_Hmac(&mac, path, addition, addlen, digest, &digest_len);
206: 	enc_digest = Qiniu_Memory_Encode(digest, digest_len);
207: 
208: 	auth = Qiniu_String_Concat("Authorization: QBox ", mac.accessKey, ":", enc_digest, NULL);
209: 	Qiniu_Free(enc_digest);
210: 
211: 	*header = curl_slist_append(*header, auth);
212: 	Qiniu_Free(auth);
213: 
214: 	return Qiniu_OK;
