static Qiniu_Error Qiniu_Count_X_Qiniu_Callback(Qiniu_Header *header, void *data)
{
	if (is_x_qiniu_header(header))
	{
		Qiniu_Count_X_Qiniu_Callback_Data *callback_data = (Qiniu_Count_X_Qiniu_Callback_Data *)data;
		callback_data->count++;
	}
	return Qiniu_OK;
}

